    fun getCategories(providerId: String, activeBaseUrl: String): List<Category> {
        val base = activeBaseUrl.trimEnd('/')
        val list = if (providerId == "prmovies_church") CHURCH_CATEGORIES else COM_CATEGORIES
        return list.map { cat ->
            val targetUrl = if (providerId == "prmovies_church" && cat.url.contains("prmovies.church")) {
                cat.url.replace("https://prmovies.church", base)
            } else if (providerId == "prmovies" && cat.url.contains("prmovies.com")) {
                cat.url.replace("https://prmovies.com", base)
            } else cat.url
            cat.copy(url = targetUrl)
        }
    }
